def unique(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

def subtract_interval(intervals, cut):
    c, d = cut
    if c == d:
        return list(intervals)

    result = []
    for a, b in intervals:
        if b <= c or a >= d:
            result.append((a, b))
        else:
            if a < c:
                result.append((a, c))
            if d < b:
                result.append((d, b))
    return result

def subtract_interval(intervals, cut):
    c, d = cut

    def rebuild(interval, start, end):
        if isinstance(interval, tuple):
            return (start, end)
        return [start, end]

    if c == d:
        return [rebuild(interval, interval[0], interval[1]) for interval in intervals]

    result = []
    for interval in intervals:
        a, b = interval

        if b <= c or a >= d:
            result.append(rebuild(interval, a, b))
        else:
            if a < c:
                result.append(rebuild(interval, a, c))
            if d < b:
                result.append(rebuild(interval, d, b))

    return result
